import re
depth = 0
stack = []
for i, line in enumerate(open('/tmp/old_instr_impl.hpp'), 1):
    s = line.strip()
    if re.match(r'#\s*(if|ifdef|ifndef)\b', s):
        depth += 1
        stack.append((i, s, depth))
    elif re.match(r'#\s*endif\b', s):
        depth -= 1
        if stack: stack.pop()
        if depth < 0: print('UNBALANCED close at', i)
print('final depth:', depth)
for e in stack: print('UNCLOSED:', e)
"

